SELECT id, user_id, device_id, measure_time, heart_rate, duration_seconds, waveform FROM t_ecg_record  AND id = #{id}
 AND user_id = #{userId}
 AND device_id = #{deviceId}
 AND measure_time = #{measureTime}
 AND heart_rate = #{heartRate}
 AND duration_seconds = #{durationSeconds} ORDER BY id DESC
